export const templateStringsByLocale: Record<'fr' | 'sw' | 'en', Record<string, string>> = {
  fr: templateStringsFr,
  sw: templateStringsSw,
  en: templateStringsEn,
};

/** Template copy for a locale, falling back to English, then to the key itself. */
export function templateString(locale: 'fr' | 'sw' | 'en', key: string): string {
  return templateStringsByLocale[locale]?.[key] ?? templateStringsEn[key] ?? key;
}
